<?php
$accounts = $pdo->query(
    "SELECT users.*, CASE users.role
        WHEN 'student' THEN students.prn
        WHEN 'faculty' THEN faculty.department
        ELSE ''
     END AS detail
     FROM users
     LEFT JOIN students ON students.user_id = users.id
     LEFT JOIN faculty ON faculty.user_id = users.id
     ORDER BY CASE users.role WHEN 'admin' THEN 1 WHEN 'warden' THEN 2 WHEN 'faculty' THEN 3 ELSE 4 END,
     users.full_name"
)->fetchAll();
?>
<section class="page-heading-row"><div><span class="eyebrow">ACCESS & PERMISSIONS</span><h1>User accounts<span class="heading-dot">.</span></h1><p>Create warden access, reset passwords, and manage active accounts.</p></div><span class="count-chip"><?= count($accounts) ?> accounts</span></section>
<section class="panel form-panel"><div class="panel-heading"><div><span class="eyebrow">STAFF ACCESS</span><h2>Create an administrator or warden</h2></div><span class="form-step">01 <i>/</i> secure access</span></div>
<form method="post" class="form-grid"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="create_staff_account"><input type="hidden" name="return_to" value="accounts">
<label class="form-field"><span>Full name</span><input name="full_name" required maxlength="120" placeholder="e.g. Priya Kulkarni"></label><label class="form-field"><span>Username</span><input name="username" required maxlength="80" placeholder="Choose a login name"></label><label class="form-field"><span>Account role</span><select name="role" required><option value="warden">Hostel warden</option><option value="admin">Administrator</option></select></label><label class="form-field"><span>Temporary password</span><input name="password" type="password" required minlength="8" placeholder="At least 8 characters"></label><div class="form-submit-row"><span>Student and faculty accounts are created from their directory pages.</span><button class="button button-primary" type="submit">Create staff account <span>→</span></button></div></form></section>
<section class="panel table-panel"><div class="panel-heading"><div><span class="eyebrow">CAMPUS ACCESS</span><h2>All accounts</h2></div><span class="table-caption"><?= count($accounts) ?> total</span></div>
<?php if ($accounts): ?><div class="table-scroll"><table><thead><tr><th>ACCOUNT</th><th>ROLE</th><th>PROFILE DETAIL</th><th>STATUS</th><th>RESET PASSWORD</th><th>ACCESS</th></tr></thead><tbody><?php foreach ($accounts as $index => $account): ?><tr><td><span class="person-cell"><span class="person-avatar person-color-<?= $index % 5 ?>"><?= e(strtoupper(substr($account['full_name'], 0, 1))) ?></span><span><b><?= e($account['full_name']) ?><?= (int) $account['id'] === (int) $user['id'] ? ' (you)' : '' ?></b><small>@<?= e($account['username']) ?></small></span></span></td><td><?= e(user_role_label($account['role'])) ?></td><td><?= e($account['detail'] ?: '—') ?></td><td><span class="status-badge <?= (int) $account['active'] === 1 ? 'status-resolved' : 'status-closed' ?>"><?= (int) $account['active'] === 1 ? 'Active' : 'Inactive' ?></span></td><td><form method="post" class="account-reset-form"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="reset_user_password"><input type="hidden" name="user_id" value="<?= (int) $account['id'] ?>"><input type="hidden" name="return_to" value="accounts"><input name="password" type="password" minlength="8" required placeholder="New password" aria-label="New password for <?= e($account['username']) ?>"><button class="small-action" type="submit">Reset</button></form></td><td><?php if ((int) $account['id'] !== (int) $user['id']): ?><form method="post" class="inline-form" data-confirm="<?= (int) $account['active'] === 1 ? 'Deactivate this account? It will no longer be able to sign in.' : 'Reactivate this account?' ?>"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="toggle_user"><input type="hidden" name="user_id" value="<?= (int) $account['id'] ?>"><input type="hidden" name="return_to" value="accounts"><button class="small-action <?= (int) $account['active'] === 1 ? 'small-action-danger' : '' ?>" type="submit"><?= (int) $account['active'] === 1 ? 'Deactivate' : 'Activate' ?></button></form><?php else: ?><span class="muted">Current account</span><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><div class="empty-state"><b>No accounts found</b></div><?php endif; ?></section>
<div class="report-footnote"><span>✦</span> At least one active administrator must remain. Accounts are deactivated rather than deleted so linked records remain intact.</div>
